}

coding.referenceSolution:
function matchKeys(keys, pattern) {
  const parts = pattern.split('*');
  return keys.filter((k) => {
    if (parts.length === 1) return k === pattern;
    if (!k.startsWith(parts[0])) return false;
    let pos = parts[0].length;
    for (let i = 1; i < parts.length - 1; i++) {
      const at = k.indexOf(parts[i], pos);
      if (at < 0) return false;
      pos = at + parts[i].length;
    }
    const last = parts[parts.length - 1];
    return k.length - last.length >= pos && k.endsWith(last);
  });
}

